components/products/promotion-callout:
{{!--
    Featured promotion callout.

    @param promotions Array of `{ text }`, already sorted by priority by Stencil
    @param mode "compact" on product cards (top promotion + "+N more offers"), anything else
                renders the full list — the product page shows every promotion
--}}
{{#if promotions.length}}
    {{#if mode '===' 'compact'}}
        <div class="promotionCallout promotionCallout--compact">
            <div class="promotionCallout-item">
                <span class="promotionCallout-text">{{promotions.[0].text}}</span>
            </div>
            {{#if promotions.[1]}}
                <span class="promotionCallout-more">
                    +{{subtract promotions.length 1}} {{lang 'products.featured_promotions.more_offers' count=(subtract promotions.length 1)}}
                </span>
            {{/if}}
        </div>
    {{else}}
        <ul class="promotionCallout promotionCallout--full">
            {{#each promotions}}
                <li class="promotionCallout-item">
                    <span class="promotionCallout-text">{{text}}</span>
                </li>
            {{/each}}
        </ul>
    {{/if}}
{{/if}}
